local ActionDarkDreamLevelDetailsLevelNode = Class('ActionDarkDreamLevelDetailsLevelNode')
local ChaoticRecallUtils = import("Game.UI.FightReady.ChaoticRecall.ChaoticRecallUtils")
local IconTagPath = "Game.UI.FightReady.ChaoticRecall.Cell.ActionDarkDreamIconNode"
local TeamCount = 4
local TeamNodePath = "Game.UI.FightReady.ChaoticRecall.Cell.ActionDarkDreamTeamHeadNode"

function ActionDarkDreamLevelDetailsLevelNode:__init()
    self.iconTagEnv = {}
    self.teamEnv = {}
end

function ActionDarkDreamLevelDetailsLevelNode:__delete()
    self.iconTagEnv = nil
    self.teamEnv = nil
end

function ActionDarkDreamLevelDetailsLevelNode:Awake()
    SetButtonAction(self.BtnCheck.gameObject,Bind(self,self.OnBtnCheckClick))
    self:InitTeamNode()
end

function ActionDarkDreamLevelDetailsLevelNode:InitTeamNode()
    for i = 1, TeamCount do
        local teamNode = self["BtnAddRole"..i]
        if not isNull(teamNode) then
            local env = CfUtils.GetLuaScr(teamNode,TeamNodePath)
            if env then
                table.insert(self.teamEnv,env)
            end
        end
    end
    
    if self.IconNode then
        local env = CfUtils.GetLuaScr(self.IconNode,IconTagPath)
        if not isNull(env) then
            table.insert(self.iconTagEnv,env)
        end
    end
end

function ActionDarkDreamLevelDetailsLevelNode:RefreshShow(data,questId,index,teamQuestId,groupId)
    self.data = data
    self.questId = questId
    self.teamQuestId = teamQuestId
    self.index = index
    self.groupId = groupId
    local levelVo = ChaoticRecallUtils.GetChaoticRecallLevelVo(self.questId)
    if not isNull(levelVo) then
        self:SetStaticShow(levelVo)
    end
    self:SetNum()

    self:RefreshTeamInfo()

end

function ActionDarkDreamLevelDetailsLevelNode:RefreshTeamInfo()
    ---@type TeamComponent
    local teamComponent        = GameUtils.GetEntityCompByType(ECSComponentType.Constants.TeamComponent)
    local cardInfo =  teamComponent:GetTeamByQuestId(self.teamQuestId, self.index)
    for i, v in ipairs(self.teamEnv) do
        v:RefreshTeamInfo(cardInfo[i],self.questId,self.index,self.groupId)
    end
end

function ActionDarkDreamLevelDetailsLevelNode:SetNum()
    CfUtils.FillText(self.TxtNumber,string.format("0%s",self.index))
end

function ActionDarkDreamLevelDetailsLevelNode:SetStaticShow(levelVo)
    self:SetTag(levelVo.tag)
    self:SetDes(levelVo.buffDec)
    self:SetPower(levelVo.proposalLevel)
    self:SetBossInfo()
end

function ActionDarkDreamLevelDetailsLevelNode:SetBossInfo()
    local allQuestLineup = QuestConfMgr:GetInstance():GetAllQuestLineupVo(self.questId)
    local bossId = nil
    local bossAttribute = nil
    local eliteId = nil
    local eliteAttribute = nil

    for i, v in ipairs(allQuestLineup) do
        for k, j in pairs(v.wave1NpcType) do
            if tonumber(j) == Constants.RoleClass.Boss then
                bossId = v.wave1NpcId[k]
                --- 克隆一份数据 直接覆盖需要修改的字段
                ---@type MonsterTypeVo
                local monsterTypeVo = clone(CardConfMgr:GetInstance():GetMonsterTypeVoById(v.wave1NpcId[k]))
                monsterTypeVo.monsterClass = checkNumber(j)
                if checkNumber(v.attribute[k]) > 0 then
                    bossAttribute = checkNumber(v.attribute[k])
                elseif monsterTypeVo.role > 0 then
                    local cardVo = CardConfMgr:GetInstance():GetCardBySkinRefId(monsterTypeVo.skinId)
                    bossAttribute = cardVo.attributeType
                end
            elseif tonumber(j) == Constants.RoleClass.Elite then
                eliteId = v.wave1NpcId[k]
                --- 克隆一份数据 直接覆盖需要修改的字段
                ---@type MonsterTypeVo
                local monsterTypeVo = clone(CardConfMgr:GetInstance():GetMonsterTypeVoById(eliteId))
                monsterTypeVo.monsterClass = checkNumber(j)
                if checkNumber(v.attribute[k]) > 0 then
                    eliteAttribute = checkNumber(v.attribute[k])
                elseif monsterTypeVo.role > 0 then
                    local cardVo = CardConfMgr:GetInstance():GetCardBySkinRefId(monsterTypeVo.skinId)
                    eliteAttribute = cardVo.attributeType
                end
            end
        end
    end

    self.bossId = not isNull(bossId) and bossId or not isNull(eliteId) and eliteId or nil
    local attribute = not isNull(bossId) and bossAttribute or not isNull(eliteId) and eliteAttribute or nil

    if not isNull(self.bossId) then
        local monster = CardConfMgr:GetInstance():GetBaseMonstVo(self.bossId)
        if not isNull(monster) then
            local env = CfUtils.GetLuaScr(self.BossHeadNode,"Game.Behaviours.CardHeadNode")
            if not isNull(env) then
                local rare
                local monsterClass = monster.monsterClass
                if monsterClass == Constants.RoleClass.Boss then
                    rare = Constants.RareType.SSR
                elseif monsterClass == Constants.RoleClass.Elite then
                    rare = Constants.RareType.SR
                else
                    rare = Constants.RareType.R
                end
                env:FreshMonsterUI(monster, rare, nil, attribute)
            end
        end
    end
end

function ActionDarkDreamLevelDetailsLevelNode:OnBtnCheckClick()
    CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UIBossDetailDialog, parameters = { levelId = self.questId } })
end

function ActionDarkDreamLevelDetailsLevelNode:SetPower(power)
    CfUtils.FillText(self.TxtNumFighting,power)
end

function ActionDarkDreamLevelDetailsLevelNode:SetDes(des)
    CfUtils.FillText(self.TxtTitle,des)
end

function ActionDarkDreamLevelDetailsLevelNode:SetTag(tags)
    for i = 1, self.IconList.transform.childCount do
        local tag = self.IconList.transform:GetChild(i - 1)
        CfUtils.SetActive(tag.gameObject, false)
    end
    
    for i, v in ipairs(tags) do
        if isNull(self.iconTagEnv[i]) then
            local cellItem = CS.UnityEngine.GameObject.Instantiate(self.IconNode.gameObject)
            if not isNull(cellItem) then
                KTool.SetParent(cellItem,self.IconList.gameObject,false)
            end
            
            if not isNull(cellItem) then
                local env = CfUtils.GetLuaScr(cellItem,IconTagPath)
                if not isNull(env) then
                    table.insert(self.iconTagEnv,env)
                end
            end
        end
        
        local tagVo = ChaoticRecallUtils.GetChaoticRecallRecommendTagVo(v)
        if not isNull(tagVo) then
            self.iconTagEnv[i]:RefreshTagShow(tagVo.icon)
        end
        CfUtils.SetActive(self.iconTagEnv[i].controller.gameObject,true)
    end
end

function ActionDarkDreamLevelDetailsLevelNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return ActionDarkDreamLevelDetailsLevelNode